static int aspeed_g5_sig_expr_eval ( struct aspeed_pinmux_data * ctx , const struct aspeed_sig_expr * expr , bool enabled ) { int ret ; int i ; for ( i = 0 ; i < expr -> ndescs ; i ++ ) { const struct aspeed_sig_desc * desc = & expr -> descs [ i ] ; struct regmap * map ; map = aspeed_g5_acquire_regmap ( ctx , desc -> ip ) ; if ( IS_ERR ( map ) ) { dev_err ( ctx -> dev , "Failed to acquire regmap for IP block %d\n" , desc -> ip ) ; return PTR_ERR ( map ) ; } if ( ret <= 0 ) { return ret ; } } return 1 ; } 